import unittest
from cache import CustomerCache
class Smoke(unittest.TestCase):
 def test_roundtrip(self):
  c=CustomerCache();c.put('a','x',7);self.assertEqual(c.get('a','x'),7);c.invalidate('a');self.assertIsNone(c.get('a','x'))

class Contract(unittest.TestCase):
 def test_same_item_different_tenants_is_isolated(self):
  c=CustomerCache();c.put('a','k',1);c.put('b','k',2)
  self.assertEqual(c.get('a','k'),1);self.assertEqual(c.get('b','k'),2)
  self.assertIsNone(c.get('c','k'))
 def test_put_replaces_only_that_pair(self):
  c=CustomerCache();c.put('a','x',1);c.put('a','y',2)
  self.assertEqual(c.get('a','x'),1);self.assertEqual(c.get('a','y'),2)
  c.put('a','x',3)
  self.assertEqual(c.get('a','x'),3);self.assertEqual(c.get('a','y'),2)
  self.assertEqual(c.get('b','x'),None)
 def test_falsy_values_preserved(self):
  for v in (0,False,''):
   c=CustomerCache();c.put('a','x',v);self.assertEqual(c.get('a','x'),v)
 def test_missing_pair_returns_none(self):
  c=CustomerCache();c.put('a','x',1)
  self.assertIsNone(c.get('a','missing'));self.assertIsNone(c.get('missing','x'))
 def test_invalidate_only_that_tenant(self):
  c=CustomerCache();c.put('a','x',1);c.put('b','x',2);c.put('b','y',3)
  c.invalidate('a')
  self.assertIsNone(c.get('a','x'))
  self.assertEqual(c.get('b','x'),2);self.assertEqual(c.get('b','y'),3)
 def test_invalidate_unknown_tenant_is_safe(self):
  c=CustomerCache();c.put('a','x',1);c.invalidate('nope');self.assertEqual(c.get('a','x'),1)
 def test_colon_delimited_ids(self):
  c=CustomerCache();c.put('a:b','c',1);c.put('a','b:c',2);c.put('a:b','c:d',3)
  self.assertEqual(c.get('a:b','c'),1);self.assertEqual(c.get('a','b:c'),2);self.assertEqual(c.get('a:b','c:d'),3)
  self.assertIsNone(c.get('a','c'))
 def test_invalidate_each_tenant_independently(self):
  c=CustomerCache();c.put('a','x',1);c.put('b','x',2)
  c.invalidate('a');c.put('a','y',3)
  self.assertEqual(c.get('a','y'),3);self.assertIsNone(c.get('a','x'));self.assertEqual(c.get('b','x'),2)

